INSERT INTO content1 (id, en, tr, fr, de, es, it, fa, `level`) VALUES(307,"As far as i recall, the meeting was planned to be made in the last days was canceled due to the lack of participant.","Hatırladığım kadarıyla, son günlerde yapılması planlanan toplantı katılımcı yetersizliğinden dolayı iptal edildi.","Autant que je me souvienne, la réunion qui devait avoir lieu dans les derniers jours a été annulée en raison du manque de participant.","Soweit ich mich erinnere, wurde das Treffen, das in den letzten Tagen geplant war, wegen fehlender Teilnehmer abgesagt.","Por lo que recuerdo, la reunión que estaba planeada para realizarse en los últimos días fue cancelada debido a la falta de participantes.","Per quanto mi ricordo, l'incontro che doveva essere fatto negli ultimi giorni è stato annullato per mancanza di partecipanti.","تا جایی که به یاد دارم، جلسه قرار بود در روزهای آخر برگزار شود، به دلیل عدم حضور شرکت کنندگان لغو شد",5);
INSERT INTO content1 (id, en, tr, fr, de, es, it, fa, `level`) VALUES(308,"Why is the construction of houses too late?","Evlerin inşası neden çok geç kaldı?","Pourquoi la construction de maisons est-elle trop tardive ?","Warum kommt der Hausbau zu spät?","¿Por qué la construcción de casas es demasiado tarde?","Perché la costruzione delle case è troppo tardi?","چرا ساخت خانه ها دیر می شود؟",1);
INSERT INTO content1 (id, en, tr, fr, de, es, it, fa, `level`) VALUES(309,"The forecast of future sales is really impressive.","Gelecek satışların tahmini gerçekten etkileyici.","La prévision des ventes futures est vraiment impressionnante.","Die Prognose der zukünftigen Umsätze ist wirklich beeindruckend.","El pronóstico de ventas futuras es realmente impresionante.","La previsione delle vendite future è davvero impressionante.","پیش بینی فروش آینده واقعاً چشمگیر است",1);
INSERT INTO content1 (id, en, tr, fr, de, es, it, fa, `level`) VALUES(310,"I think, your words are as valuable as your beauty.","Bence sözlerin güzelliğin kadar değerli.","Je pense que tes paroles sont aussi précieuses que ta beauté.","Ich denke, deine Worte sind so wertvoll wie deine Schönheit.","Creo que tus palabras son tan valiosas como tu belleza.","Penso che le tue parole valgano quanto la tua bellezza.","من فکر می کنم، کلمات شما به اندازه زیبایی شما ارزشمند هستند",1);
INSERT INTO content1 (id, en, tr, fr, de, es, it, fa, `level`) VALUES(311,"Many global companies are in poor condition because of crisis.","Birçok küresel şirket, krizden dolayı kötü durumda.","De nombreuses entreprises mondiales sont en mauvais état à cause de la crise.","Viele globale Unternehmen befinden sich aufgrund der Krise in einem schlechten Zustand.","Muchas empresas globales están en malas condiciones debido a la crisis.","Molte aziende globali sono in cattive condizioni a causa della crisi.","بسیاری از شرکت های جهانی به دلیل بحران در وضعیت بدی هستند",1);
INSERT INTO content1 (id, en, tr, fr, de, es, it, fa, `level`) VALUES(312,"Despite deteriorations in economy, some sectors are still standing.","Ekonomideki bozulmalara rağmen, bazı sektörler hala ayakta duruyor.","Malgré les détériorations de l'économie, certains secteurs sont encore debout.","Trotz Verschlechterungen der Wirtschaft stehen einige Sektoren noch.","A pesar del deterioro de la economía, algunos sectores siguen en pie.","Nonostante il deterioramento dell'economia, alcuni settori sono ancora in piedi.","با وجود وخامت اقتصاد، برخی از بخش ها همچنان پابرجا هستند",2);